@'
import fs from 'node:fs';
for(const file of ['scripts/longitudinal-report.mjs','scripts/longitudinal-readme.mjs']) {
 let text=fs.readFileSync(file,'utf8');
 if(file.includes('readme')) text=text.replace('The baseline could keep ordinary Markdown plans and handoffs.', 'Both arms were instructed to preserve repository intent and handoffs; the baseline used ordinary Markdown.');
 else text=text.replace('No evaluator feedback or result-dependent retries were provided.', 'Both arms were instructed to preserve repository intent and handoffs; ordinary Markdown was available to the baseline. This measures DIP against an instructed durable-memory baseline, not an unassisted default chat. No evaluator feedback or result-dependent retries were provided.');
 fs.writeFileSync(file,text);
}
'@ | node --input-type=module
npx prettier --write scripts/longitudinal-report.mjs scripts/longitudinal-readme.mjs
